module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic disc,
    output logic flag,
    output logic err
);

    typedef enum logic [3:0] {
        S_IDLE  = 4'd0,
        S_1     = 4'd1,
        S_2     = 4'd2,
        S_3     = 4'd3,
        S_4     = 4'd4,
        S_5     = 4'd5,
        S_6     = 4'd6,
        S_DISC  = 4'd7,
        S_FLAG  = 4'd8,
        S_ERR   = 4'd9
    } state_t;

    state_t current_state, next_state;

    // Synchronous state register
    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= S_IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state = current_state;
        case (current_state)
            S_IDLE: begin
                if (in) next_state = S_1;
                else    next_state = S_IDLE;
            end
            S_1: begin
                if (in) next_state = S_2;
                else    next_state = S_IDLE;
            end
            S_2: begin
                if (in) next_state = S_3;
                else    next_state = S_IDLE;
            end
            S_3: begin
                if (in) next_state = S_4;
                else    next_state = S_IDLE;
            end
            S_4: begin
                if (in) next_state = S_5;
                else    next_state = S_IDLE;
            end
            S_5: begin
                if (in) next_state = S_6;
                else    next_state = S_DISC;
            end
            S_6: begin
                if (in) next_state = S_ERR;
                else    next_state = S_FLAG;
            end
            S_DISC: begin
                if (in) next_state = S_1;
                else    next_state = S_IDLE;
            end
            S_FLAG: begin
                if (in) next_state = S_1;
                else    next_state = S_IDLE;
            end
            S_ERR: begin
                if (in) next_state = S_ERR;
                else    next_state = S_IDLE;
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Moore output logic
    always_comb begin
        disc = (current_state == S_DISC);
        flag = (current_state == S_FLAG);
        err  = (current_state == S_ERR);
